// Gate: Read message let through only what concerns the bot. Here: the thread check, the history and
// the pictures. What the message means is the front agent's call.
// action: 0 link, 1 fixed reply, 2 nothing more.
const m = $('Read message').first().json;
const settings = settingsOf('Load settings');
const members = (($('Fetch members').first().json.data || {}).items || []);
const names = Object.fromEntries(members.map((x) => [x.member_id, x.name]));
const nameOf = (id) => (id === settings.lark_app_id ? 'You (the agent)' : names[id] || (id === settings.lark_open_id ? 'The owner' : 'A team member'));
// Lark returns the bot's own messages with its app id as sender.id, not its open_id.
const fromBot = (x) => Boolean(x && x.sender && x.sender.sender_type === 'app' && x.sender.id === settings.lark_app_id);
// found is the thread, or for a quoted reply the message it quotes.
const found = (($('Fetch thread').first().json.data || {}).items || []).filter((x) => x.message_id !== m.message_id);
if (m.access === 'thread_check' && !found.some(fromBot)) return [{ json: { ...m, action: 2, agent: false } }];
const history = found.slice(-30).map((x) => `${nameOf(x.sender && x.sender.id)}: ${plainOf(x).slice(0, 1500)}`);
const rootText = found.map((x) => (x.body && x.body.content) || '').join('\n');
const post = rootText.match(/[Pp]ost #(\d+)/);
const offer = rootText.match(/[Oo]ffer #(\d+)/);
const who = nameOf(m.sender);
// Pictures of this message first, then those of the thread, newest first: 10 at most, each "<message id> <key>".
const pictures = [
  ...m.images.map((k) => ({ ref: `${m.message_id} ${k}`, from: who, where: 'this message' })),
  ...[...found].reverse().flatMap((x) => imagesOf(x).map((k) => ({ ref: `${x.message_id} ${k}`, from: nameOf(x.sender && x.sender.id), where: 'earlier in the thread' }))),
].slice(0, 10);
// Full texts people wrote here: finalize_post accepts only a final version copied from one of them.
const written = [m.text, ...found.filter((x) => x.sender && x.sender.sender_type === 'user').map(plainOf)];
const out = { ...m, history, pictures, written, post_id: post ? Number(post[1]) : null, offer_id: offer ? Number(offer[1]) : null, who, reply_to: m.message_id };
if (m.access === 'reply') return [{ json: { ...out, action: 1, agent: false } }];
if (m.access === 'link_group') return [{ json: { ...out, action: 0, agent: false } }];
return [{ json: { ...out, action: m.access === 'link_owner' ? 0 : 2, agent: true } }];

const d = $('Decide').first().json;
if (d.access !== 'link_group') return [];
return [{ json: { reply_to: d.reply_to, text: 'This group is now my team chat, and everyone here is equal. @mention me, reply to one of my messages or write in my threads; send pictures the same way. /help shows what I can do. My questions, draft cards, publish notices and weekly reports come here from now on.' } }];

const d = $('Decide').first().json;
const lines = [];
if (d.access === 'link_owner') lines.push('(This is the first message from the owner: introduce yourself in two lines and, if goals or brand docs are missing, ask for them.)');
if (d.history.length) lines.push(`Conversation so far in this thread:\n${d.history.join('\n')}`);
if (d.post_id || d.offer_id) lines.push(`This thread is about ${d.post_id ? `post #${d.post_id}` : `offer #${d.offer_id}`}.`);
if (d.pictures.length) lines.push(`Pictures you can see, in this order:\n${d.pictures.map((p, i) => `Picture ${i + 1}: reference "${p.ref}", from ${p.from}, ${p.where}`).join('\n')}`);
lines.push(`${d.who} wrote now: <<<\n${d.text || '(pictures only)'}\n>>>`);
if (d.is_command) lines.push(`That is the command /${d.command}: run the ${d.command} procedure exactly.`);
lines.push('(Reply in plain text: Lark shows markdown as raw symbols.)');
return [{
  json: {
    agent: 'front',
    task: lines.join('\n\n'),
    reply_to: d.reply_to,
    auth: d.auth,
    pictures: d.pictures,
    event: {
      type: (d.post_id && (d.parent_id || d.thread_id)) ? 'change_request' : 'manager_note',
      post_id: d.post_id,
      offer_id: d.offer_id,
      text: `${d.who}: ${d.text}${(d.images || []).length ? ` [${d.images.length} picture(s)]` : ''}`,
    },
  },
}];

const a = $('Agent input').first().json;
return a.pictures.map((p) => {
  const [messageId, key] = p.ref.split(' ');
  return { json: { message_id: messageId, key, auth: a.auth } };
});

const a = $('Agent input').first().json;
const c = $('Get context').first().json;
// The agent passes every image binary of its input item to the model: picture_1, picture_2, ...
const binary = {};
const missing = [];
if ($('Download picture').isExecuted) {
  $('Download picture').all().forEach((item, i) => {
    const b = item.binary && item.binary.data;
    if (b && String(b.mimeType || '').startsWith('image/')) binary[`picture_${i + 1}`] = b;
    else missing.push(i + 1);
  });
}
const note = missing.length ? `\n\n(Picture ${missing.join(', ')} could not be downloaded, so you cannot see ${missing.length > 1 ? 'them' : 'it'}.)` : '';
return [{ json: { system: c.system, task: a.task + note }, binary }];

const out = String($('Front agent').first().json.output || '').trim();
// NO_REPLY: a thread message meant for someone else.
return out && out !== 'NO_REPLY' ? [{ json: { text: out, reply_to: $('Agent input').first().json.reply_to } }] : [];
